mod max_message_bytes {
    use super::common::Harness;
    use serde_json::json;

    fn create(h: &mut Harness, attributes: serde_json::Value) {
        h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": attributes}));
    }

    fn send(h: &mut Harness, body: &str) -> Result<(), String> {
        let command = json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
        let response = h.run(command);
        match response["ok"] == true {
            true => Ok(()),
            false => Err(response["error"]["code"].as_str().unwrap().to_owned()),
        }
    }

    #[test]
    fn limit_counts_utf8_bytes() {
        let mut h = Harness::new();
        create(&mut h, json!({"MaxMessageBytes": 4}));
        assert_eq!(send(&mut h, "abcd"), Ok(()));
        assert_eq!(send(&mut h, "abcde"), Err("InvalidParameterValue".into()));
        // two characters, four bytes
        assert_eq!(send(&mut h, "\u{e9}\u{e9}"), Ok(()));
        // two characters, six bytes
        assert_eq!(send(&mut h, "\u{20ac}\u{20ac}"), Err("InvalidParameterValue".into()));
    }

    #[test]
    fn rule_comes_before_fifo_rules() {
        let mut h = Harness::new();
        h.ok(json!({"Command": "CreateQueue", "QueueName": "q.fifo",
            "Attributes": {"Fifo": true, "MaxMessageBytes": 1}}));
        // no GroupId, which would be MissingParameter, but the body is too long
        assert_eq!(
            h.err(json!({"Command": "SendMessage", "QueueName": "q.fifo", "Body": "ab"})),
            "InvalidParameterValue"
        );
    }

    #[test]
    fn set_attributes_applies_to_later_sends_only() {
        let mut h = Harness::new();
        create(&mut h, json!({}));
        assert_eq!(send(&mut h, "abcdef"), Ok(()));
        h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
            "Attributes": {"MaxMessageBytes": 3}}));
        assert_eq!(send(&mut h, "abcdef"), Err("InvalidParameterValue".into()));
        let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
        assert_eq!(r["Attributes"]["MaxMessageBytes"], 3);
        assert_eq!(r["Counts"]["Visible"], 1);
    }

    #[test]
    fn attribute_range_is_one_to_1024() {
        let mut h = Harness::new();
        for bad in [json!(0), json!(1025), json!("5"), json!(5.5)] {
            assert_eq!(
                h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                    "Attributes": {"MaxMessageBytes": bad}})),
                "InvalidParameterValue"
            );
        }
        create(&mut h, json!({"MaxMessageBytes": 1024}));
        // the same value as the default counts as equal in CreateQueue rule 4
        create(&mut h, json!({}));
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 10}})),
            "QueueAlreadyExists"
        );
    }

    #[test]
    fn dead_letter_move_ignores_limit() {
        let mut h = Harness::new();
        h.ok(json!({"Command": "CreateQueue", "QueueName": "dead",
            "Attributes": {"MaxMessageBytes": 1}}));
        h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
            "Attributes": {"DeadLetterQueue": "dead", "MaxReceiveCount": 1, "VisibilityTimeout": 0}}));
        assert_eq!(send(&mut h, "long body"), Ok(()));
        h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
        h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
        let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dead"}));
        assert_eq!(r["Messages"][0]["Body"], "long body");
    }
}
