        .collect();
    assert_eq!(handles, ["r-1", "r-2"]);
    let r = h.ok(json!({"Command": "DeleteMessageBatch", "QueueName": "q", "Entries": [
        {"Id": "x", "ReceiptHandle": "r-1"},
        {"Id": "y", "ReceiptHandle": "r-1"},
